using System;
using System.Collections.Generic;
using UnityEngine;
using Random = UnityEngine.Random;

/// <summary>
/// 商店管理器 — 挂载在 Shop 房间预制体的根节点上。
///
/// 与其他房间一样，道具从 RoomConfig.itemPool 生成。
/// 区别在于：生成的 ItemPickup 打上 IsShopItem=true 标记，
/// ItemInteractionHandler 靠近时会显示购买 UI 而非拾取 UI。
///
/// 流程:
///   OpenShop()  ─→  从 RoomConfig.itemPool 随机抽 slotCount 个，在 spawn point 生成并标记 IsShopItem
///   CloseShop() ─→  清理所有未购买的拾取物
/// </summary>
public class ShopManager : MonoBehaviour
{
    [Header("商店参数")]
    [Tooltip("每次开张生成的商品数量")]
    [Range(1, 12)] public int slotCount = 4;

    [Header("打折（可选）")]
    [Range(0f, 1f)] public float discount = 0f;

    /// <summary>商店是否已开张</summary>
    public bool IsOpen { get; private set; }

    /// <summary>已生成的拾取物数量</summary>
    public int SpawnedCount => _spawnedPickups.Count;

    // ========== 事件 ==========

    /// <summary>任意 ShopManager 实例化就绪时触发</summary>
    public static event Action<ShopManager> OnAnyShopManagerReady;

    /// <summary>所有商品被买空</summary>
    public event Action OnAllItemsSold;

    // ========== 内部状态 ==========

    private readonly List<ItemPickup> _spawnedPickups = new();

    private void Awake()
    {
        OnAnyShopManagerReady?.Invoke(this);
    }

    private void OnDestroy()
    {
        CloseShop();
    }

    /// <summary>开张 — 在物品生成点生成带商店标记的拾取物</summary>
    public void OpenShop()
    {
        var roomRoot = GetComponent<RoomRoot>();
        if (roomRoot == null || roomRoot.config == null)
        {
            Debug.LogError("[ShopManager] RoomRoot 或 RoomConfig 不存在！", this);
            return;
        }

        var cfg = roomRoot.config;

        var library = ItemsLibrary.Instance;
        if (library == null)
        {
            Debug.LogWarning("[ShopManager] ItemsLibrary 未找到，无法开张");
            return;
        }

        CloseShop();

        // 确定池和权重
        var pool = (cfg.itemPool != null && cfg.itemPool.Count > 0) ? cfg.itemPool : null;
        var weights = (cfg.qualityWeights != null && cfg.qualityWeights.Length > 0) ? cfg.qualityWeights : null;
        var filter = ItemPoolFilter.GetPlayerItemManager();

        var picked = library.GetRandomItemPrefabs(slotCount, pool, weights, filter);
        if (picked.Count == 0)
        {
            Debug.Log("[ShopManager] 道具池为空或全部已达上限，商店无法开张");
            IsOpen = false;
            return;
        }

        var spawnPoints = roomRoot.itemSpawnPoints;
        int spawnPointCount = spawnPoints != null ? spawnPoints.Length : 0;

        for (int i = 0; i < picked.Count; i++)
        {
            var prefab = picked[i];
            if (prefab == null) continue;

            Vector3 spawnPos;
            if (i < spawnPointCount && spawnPoints[i] != null)
                spawnPos = spawnPoints[i].position;
            else
                spawnPos = transform.position + (Vector3)(Random.insideUnitCircle * 2f);

            var go = Instantiate(prefab, spawnPos, Quaternion.identity, transform);
            go.name = $"ShopItem_{prefab.name}";

            var pickup = go.GetComponent<ItemPickup>();
            if (pickup == null)
                pickup = go.AddComponent<ItemPickup>();
            pickup.IsShopItem = true;

            _spawnedPickups.Add(pickup);
        }

        IsOpen = true;
        Debug.Log($"[ShopManager] 商店开张，生成了 {_spawnedPickups.Count} 件商品");
    }

    /// <summary>打烊 — 清理所有未购买的拾取物</summary>
    public void CloseShop()
    {
        IsOpen = false;

        foreach (var pickup in _spawnedPickups)
        {
            if (pickup != null && pickup.gameObject != null)
                Destroy(pickup.gameObject);
        }
        _spawnedPickups.Clear();
    }

    /// <summary>拾取物被购买后回调（由 ItemInteractionHandler 调用）</summary>
    public void NotifyItemPurchased(ItemPickup pickup)
    {
        if (pickup == null) return;
        _spawnedPickups.Remove(pickup);

        Debug.Log($"[ShopManager] 售出: {pickup.itemData?.itemName}");

        _spawnedPickups.RemoveAll(p => p == null);
        if (_spawnedPickups.Count == 0 && IsOpen)
        {
            IsOpen = false;
            OnAllItemsSold?.Invoke();
        }
    }
}

using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// 商店购买弹窗 — 玩家靠近标记为 IsShopItem 的 ItemPickup 时悬浮显示。
/// 显示道具信息 + 价格 + 购买按钮。
/// Screen Space Overlay，跟随拾取物世界坐标。
/// </summary>
public class ShopItemPurchasePopup : MonoBehaviour
{
    [Header("UI 元素")]
    [SerializeField] private CanvasGroup _canvasGroup;
    [SerializeField] private Image _background;
    [SerializeField] private Image _icon;
    [SerializeField] private TMP_Text _nameText;
    [SerializeField] private TMP_Text _descText;
    [SerializeField] private TMP_Text _priceText;
    [SerializeField] private TMP_Text _promptText;
    [SerializeField] private Button _buyButton;

    [Header("样式")]
    [SerializeField] private float _fadeSpeed = 10f;
    [SerializeField] private Vector2 _screenOffset = new Vector2(0, 100f);

    [Header("购买按键")]
    [SerializeField] private KeyCode _buyKey = KeyCode.F;

    /// <summary>当前正在展示的拾取物</summary>
    public ItemPickup CurrentTarget { get; private set; }

    public bool IsVisible { get; private set; }

    private RectTransform _rect;
    private Camera _mainCam;

    private void Awake()
    {
        _rect = GetComponent<RectTransform>();
        _mainCam = Camera.main;
        if (_canvasGroup != null) _canvasGroup.alpha = 0f;

        if (_buyButton != null)
            _buyButton.onClick.AddListener(OnBuyClicked);

        gameObject.SetActive(false);
    }

    private void Update()
    {
        if (CurrentTarget == null || !IsVisible) return;

        // F 键购买
        if (Input.GetKeyDown(_buyKey))
        {
            // 购买由 ItemInteractionHandler 统一处理 F 键
            // 这里只做按钮点击的备选
            OnBuyClicked();
        }
    }

    private void LateUpdate()
    {
        if (CurrentTarget == null || !IsVisible)
        {
            if (_canvasGroup != null && _canvasGroup.alpha > 0f)
                _canvasGroup.alpha = Mathf.MoveTowards(_canvasGroup.alpha, 0f, _fadeSpeed * Time.deltaTime);
            return;
        }

        // 跟随世界坐标
        if (_mainCam != null)
        {
            Vector3 screenPos = _mainCam.WorldToScreenPoint(CurrentTarget.transform.position);
            _rect.position = screenPos + (Vector3)_screenOffset;
        }

        if (_canvasGroup != null)
            _canvasGroup.alpha = Mathf.MoveTowards(_canvasGroup.alpha, 1f, _fadeSpeed * Time.deltaTime);
    }

    /// <summary>显示弹窗</summary>
    public void Show(ItemPickup pickup)
    {
        if (pickup == null || pickup.itemData == null) return;

        // 如果正在显示另一个，先隐藏
        if (CurrentTarget != null && CurrentTarget != pickup)
            Hide();

        CurrentTarget = pickup;
        gameObject.SetActive(true);
        IsVisible = true;

        var data = pickup.itemData;

        if (_icon != null)
        {
            _icon.sprite = data.icon;
            _icon.enabled = data.icon != null;
        }
        if (_nameText != null)
        {
            _nameText.text = data.itemName;
            _nameText.color = ItemPickup.QualityToColor(data.quality);
        }
        if (_descText != null)
            _descText.text = data.description;

        RefreshPrice(pickup);

        if (_background != null)
            _background.color = new Color(0.05f, 0.05f, 0.1f, 0.92f);
    }

    /// <summary>隐藏弹窗</summary>
    public void Hide()
    {
        CurrentTarget = null;
        IsVisible = false;
        gameObject.SetActive(false);
    }

    /// <summary>刷新价格显示（ATP 变化时由 ItemInteractionHandler 调用）</summary>
    public void RefreshPrice(ItemPickup pickup)
    {
        if (pickup == null) return;

        int price = pickup.ShopPrice;
        var cm = ResolveCurrencyManager();

        bool canAfford = cm != null && cm.ATP >= price;
        int currentATP = cm != null ? cm.ATP : 0;

        if (_priceText != null)
        {
            _priceText.text = canAfford
                ? $"<color=#D9AA4D>{price} ATP</color>"
                : $"<color=#FF4444>{price} ATP</color>  (当前: {currentATP})";
        }

        if (_promptText != null)
        {
            _promptText.text = canAfford
                ? $"[F] 购买"
                : $"<color=#FF4444>ATP 不足</color>";
        }

        if (_buyButton != null)
            _buyButton.interactable = canAfford;
    }

    private void OnBuyClicked()
    {
        if (CurrentTarget == null) return;

        // 直接执行购买逻辑
        var player = PlayerManager.Instance?.CurrentPlayer;
        if (player == null) player = GameObject.FindGameObjectWithTag("Player");
        if (player == null) return;

        var cm = player.GetComponent<CurrencyManager>();
        var im = player.GetComponent<ItemManager>();
        if (cm == null || im == null) return;

        int price = CurrentTarget.ShopPrice;
        if (!cm.Spend(price))
        {
            RefreshPrice(CurrentTarget);
            return;
        }

        im.AcquireItem(CurrentTarget.itemData);

        var pickup = CurrentTarget;
        Hide();
        Destroy(pickup.gameObject);
    }

    private CurrencyManager ResolveCurrencyManager()
    {
        var player = PlayerManager.Instance?.CurrentPlayer;
        if (player == null) player = GameObject.FindGameObjectWithTag("Player");
        return player != null ? player.GetComponent<CurrencyManager>() : null;
    }
}

using UnityEngine;

/// <summary>
/// 道具 UI Controller — 监听 ItemManager(Model), 通知 ItemPanel(View)。
/// 本类是 Model ↔ View 的唯一耦合点, 沿用 SkillUIController 的模式。
/// </summary>
public class ItemUIController : MonoBehaviour
{
    [Header("Model 引用")]
    [SerializeField] private ItemManager _itemManager;

    [Header("View 引用")]
    [SerializeField] private ItemPanel _panel;

    [Header("初始容量")]
    [SerializeField] private int _initialSlotCount = 16;

    // ==================== 生命周期 ====================

    private void Start()
    {
        if (_itemManager == null)
            _itemManager = ResolveItemManager();

        if (_itemManager == null)
        {
            Debug.LogError("ItemUIController: ItemManager 未赋值", this);
            return;
        }
        if (_panel == null)
        {
            Debug.LogError("ItemUIController: ItemPanel 未赋值", this);
            return;
        }

        _panel.Initialize(_initialSlotCount);

        _itemManager.OnItemAcquired += HandleItemAcquired;
        _itemManager.OnItemRemoved += HandleItemRemoved;

        SyncAll();
    }

    private void OnDestroy()
    {
        if (_itemManager != null)
        {
            _itemManager.OnItemAcquired -= HandleItemAcquired;
            _itemManager.OnItemRemoved -= HandleItemRemoved;
        }
    }

    // ==================== Model 事件回调 ====================

    private void HandleItemAcquired(ItemData item)
    {
        // 找到该道具在列表中的索引
        var items = _itemManager.Items;
        int idx = -1;
        for (int i = 0; i < items.Count; i++)
        {
            if (items[i] == item) { idx = i; break; }
        }
        if (idx >= 0) SyncSlot(idx, item);
    }

    private void HandleItemRemoved(ItemData item)
    {
        SyncAll();
    }

    // ==================== 核心同步 ====================

    private void SyncAll()
    {
        var items = _itemManager.Items;
        for (int i = 0; i < items.Count; i++)
            SyncSlot(i, items[i]);

        // 隐藏空槽
        for (int i = items.Count; i < _initialSlotCount; i++)
            _panel.ClearSlot(i);
    }

    private void SyncSlot(int index, ItemData item)
    {
        int count = _itemManager.GetItemCount(item.itemId);
        ItemViewData data = new ItemViewData
        {
            Icon = item.icon,
            Name = item.itemName,
            Description = item.description,
            Quality = item.quality,
            Count = count
        };
        _panel.RefreshSlot(index, data, item);
    }

    // ==================== 查找 ====================

    private static ItemManager ResolveItemManager()
    {
        if (PlayerManager.Instance != null && PlayerManager.Instance.CurrentPlayer != null)
            return PlayerManager.Instance.CurrentPlayer.GetComponent<ItemManager>();

        var player = GameObject.FindGameObjectWithTag("Player");
        return player != null ? player.GetComponent<ItemManager>() : null;
    }
}

using UnityEngine;
using TMPro;

/// <summary>
/// 道具 UI 面板 — 左上角水平排列，透明背景，鼠标悬停显示详情。
/// 仅在有道具时显示槽位，空槽不留占位。
/// </summary>
public class ItemPanel : MonoBehaviour
{
    [Header("预制体与容器")]
    [SerializeField] private ItemSlotView _slotPrefab;
    [SerializeField] private Transform _container;

    [Header("悬停提示")]
    [SerializeField] private GameObject _hoverTooltip;
    [SerializeField] private TMP_Text _hoverName;
    [SerializeField] private TMP_Text _hoverDesc;

    [Header("布局")]
    [SerializeField] private int _maxSlots = 30;

    public static ItemPanel Instance { get; private set; }

    private ItemSlotView[] _views = System.Array.Empty<ItemSlotView>();

    private void Awake()
    {
        Instance = this;
        if (_hoverTooltip != null) _hoverTooltip.SetActive(false);
    }

    /// <summary>初始化，不预建空槽位（透明背景策略）</summary>
    public void Initialize(int slotCount)
    {
        int count = Mathf.Min(slotCount, _maxSlots);
        _views = new ItemSlotView[count];
    }

    public void RefreshSlot(int index, in ItemViewData data, ItemData boundItem)
    {
        if (index < 0 || index >= _maxSlots) return;

        // 按需扩容
        if (index >= _views.Length)
            ExpandSlots(index + 1);

        // 按需创建（懒加载）
        if (_views[index] == null)
        {
            var view = Instantiate(_slotPrefab, _container);
            view.name = $"ItemSlot_{index}";
            _views[index] = view;
        }

        _views[index].Refresh(data, boundItem);
    }

    public void ClearSlot(int index)
    {
        if (index < 0 || index >= _views.Length) return;
        if (_views[index] == null) return;

        SafeDestroy(_views[index].gameObject);
        _views[index] = null;
    }

    /// <summary>鼠标悬停到槽位时显示详情</summary>
    public void ShowHoverTooltip(ItemSlotView slot)
    {
        if (slot?.BoundItem == null) return;

        var item = slot.BoundItem;
        if (_hoverName != null)
        {
            _hoverName.text = item.itemName;
            _hoverName.color = ItemPickup.QualityToColor(item.quality);
        }
        if (_hoverDesc != null)
            _hoverDesc.text = item.description;

        if (_hoverTooltip != null)
        {
            _hoverTooltip.SetActive(true);
            var rt = _hoverTooltip.GetComponent<RectTransform>();
            if (rt != null)
                rt.position = slot.transform.position + new Vector3(40f, 40f, 0f);
        }
    }

    /// <summary>鼠标离开时隐藏详情</summary>
    public void HideHoverTooltip()
    {
        if (_hoverTooltip != null)
            _hoverTooltip.SetActive(false);
    }

    private void ExpandSlots(int newSize)
    {
        int target = Mathf.Min(newSize, _maxSlots);
        if (target <= _views.Length) return;

        var newViews = new ItemSlotView[target];
        for (int i = 0; i < _views.Length; i++)
            newViews[i] = _views[i];
        _views = newViews;
    }

    private static void SafeDestroy(Object obj)
    {
        if (obj == null) return;
        if (Application.isPlaying) Destroy(obj);
        else DestroyImmediate(obj);
    }
}

using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
using TMPro;

/// <summary>
/// 道具槽位 View — 纯渲染，鼠标悬停时弹出详情 tooltip。
/// 由 ItemPanel 管理，由 ItemUIController 调用 Refresh() 更新。
/// </summary>
public class ItemSlotView : MonoBehaviour, IPointerEnterHandler, IPointerExitHandler
{
    [Header("图标")]
    [SerializeField] private Image _icon;
    [SerializeField] private GameObject _emptyIcon;

    [Header("品质框")]
    [SerializeField] private Image _qualityFrame;

    [Header("信息")]
    [SerializeField] private TMP_Text _nameText;
    [SerializeField] private TMP_Text _countText;

    /// <summary>当前绑定的道具数据</summary>
    public ItemData BoundItem { get; private set; }

    private Image _background;

    private void Awake()
    {
        _background = GetComponent<Image>();
    }

    public void Refresh(in ItemViewData data, ItemData boundItem)
    {
        BoundItem = boundItem;

        // 有道具时显示极微弱的暗底
        if (_background != null)
            _background.color = new Color(0.1f, 0.1f, 0.12f, 0.3f);

        if (_icon != null)
        {
            _icon.sprite = data.Icon;
            _icon.enabled = data.Icon != null;
        }
        if (_emptyIcon != null)
            _emptyIcon.SetActive(data.Icon == null);

        if (_qualityFrame != null)
        {
            // 品质框只显示为颜色边框，Image 设为透明底色 + 薄边框效果
            _qualityFrame.color = new Color(
                QualityToColor(data.Quality).r,
                QualityToColor(data.Quality).g,
                QualityToColor(data.Quality).b,
                0.35f);
            _qualityFrame.gameObject.SetActive(true);
        }

        if (_nameText != null)
        {
            _nameText.text = data.Name;
            _nameText.color = QualityToColor(data.Quality);
        }

        if (_countText != null)
        {
            _countText.text = data.Count > 1 ? $"x{data.Count}" : "";
            _countText.gameObject.SetActive(data.Count > 1);
        }
    }

    public void SetEmpty()
    {
        BoundItem = null;

        if (_background != null)
            _background.color = new Color(0f, 0f, 0f, 0f); // 完全透明

        if (_icon != null) _icon.enabled = false;
        if (_emptyIcon != null) _emptyIcon.SetActive(false);
        if (_qualityFrame != null) _qualityFrame.gameObject.SetActive(false);
        if (_nameText != null) _nameText.text = "";
        if (_countText != null) _countText.text = "";
    }

    // ==================== 鼠标悬停 ====================

    public void OnPointerEnter(PointerEventData eventData)
    {
        ItemPanel.Instance?.ShowHoverTooltip(this);
    }

    public void OnPointerExit(PointerEventData eventData)
    {
        ItemPanel.Instance?.HideHoverTooltip();
    }

    // ==================== 工具 ====================

    private static Color QualityToColor(ItemQuality quality) => quality switch
    {
        ItemQuality.Common    => new Color(0.78f, 0.78f, 0.78f),
        ItemQuality.Uncommon  => new Color(0.36f, 0.65f, 1f),
        ItemQuality.Rare      => new Color(0.68f, 0.36f, 1f),
        ItemQuality.Legendary => new Color(1f, 0.65f, 0.15f),
        _                     => Color.white
    };
}

using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// 道具详情弹窗 — 玩家靠近道具时悬浮显示。
/// Screen Space Overlay，跟随道具世界坐标。
/// 挂在 Canvas 下的空 GameObject 上。
/// </summary>
public class ItemDetailPopup : MonoBehaviour
{
    [Header("UI 元素")]
    [SerializeField] private CanvasGroup _canvasGroup;
    [SerializeField] private Image _background;
    [SerializeField] private Image _icon;
    [SerializeField] private TMP_Text _nameText;
    [SerializeField] private TMP_Text _descText;
    [SerializeField] private TMP_Text _promptText;

    [Header("样式")]
    [SerializeField] private float _fadeSpeed = 10f;
    [SerializeField] private Vector2 _screenOffset = new Vector2(0, 80f);

    public bool IsVisible { get; private set; }

    private RectTransform _rect;
    private ItemPickup _currentTarget;
    private Camera _mainCam;

    private void Awake()
    {
        _rect = GetComponent<RectTransform>();
        _mainCam = Camera.main;
        if (_canvasGroup != null) _canvasGroup.alpha = 0f;
        gameObject.SetActive(false);
    }

    public void Show(ItemPickup pickup)
    {
        if (pickup == null || pickup.itemData == null) return;

        _currentTarget = pickup;
        gameObject.SetActive(true);

        var data = pickup.itemData;

        if (_icon != null)
        {
            _icon.sprite = data.icon;
            _icon.enabled = data.icon != null;
        }
        if (_nameText != null)
        {
            _nameText.text = data.itemName;
            _nameText.color = ItemPickup.QualityToColor(data.quality);
        }
        if (_descText != null)
            _descText.text = data.description;
        if (_promptText != null)
            _promptText.text = "[F] 拾取";

        if (_background != null)
            _background.color = new Color(0.05f, 0.05f, 0.1f, 0.9f);

        IsVisible = true;
    }

    public void Hide()
    {
        _currentTarget = null;
        IsVisible = false;
        gameObject.SetActive(false);
    }

    private void LateUpdate()
    {
        if (_currentTarget == null || !IsVisible)
        {
            if (_canvasGroup != null && _canvasGroup.alpha > 0f)
                _canvasGroup.alpha = Mathf.MoveTowards(_canvasGroup.alpha, 0f, _fadeSpeed * Time.deltaTime);
            return;
        }

        if (_mainCam != null)
        {
            Vector3 screenPos = _mainCam.WorldToScreenPoint(_currentTarget.transform.position);
            _rect.position = screenPos + (Vector3)_screenOffset;
        }

        if (_canvasGroup != null)
            _canvasGroup.alpha = Mathf.MoveTowards(_canvasGroup.alpha, 1f, _fadeSpeed * Time.deltaTime);
    }
}

using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// 道具详情面板 — 点击道具槽位时显示完整信息。
/// 位于 ItemPanel 旁或覆盖层。
