/// <summary>
/// 道具 UI Controller — 监听 ItemManager(Model), 通知 ItemPanel(View)。
/// 本类是 Model ↔ View 的唯一耦合点, 沿用 SkillUIController 的模式。
/// </summary>
public class ItemUIController : MonoBehaviour
