                QualityToColor(data.Quality).g,
                QualityToColor(data.Quality).b,
                0.35f);
            _qualityFrame.gameObject.SetActive(true);
        }

        if (_nameText != null)
        {
            _nameText.text = data.Name;
            _nameText.color = QualityToColor(data.Quality);
        }

